46	// clang-format off
47	
48	template <uint N>
49	uchar4 remapC(const NVCVChannelManip manip)
50	{
51	    static_assert(N > 0 && N <= 4, "Number of remap channels must be >= 1 and <= 4.");
52	
53	    if (manip == NVCV_CHANNEL_REVERSE)
54	    {
55	        if constexpr (N == 1) return uchar4{0, 0, 0, 0};
56	        if constexpr (N == 2) return uchar4{1, 0, 0, 0};
57	        if constexpr (N == 3) return uchar4{2, 1, 0, 0};
58	        if constexpr (N == 4) return uchar4{3, 2, 1, 0};
59	    }
60	    return uchar4{0, 1, 2, 3};
61	}
62	
63	template<typename DstT, uint N>
64	class DstMap {
65	public:
66	    using DstType = DstT;
67	
68	    static_assert(N > 0 && N <= 4, "Number of DstMap channels must be >= 1 and <= 4.");
69	
70	    DstMap(DstT *dst, size_t addN, int addH, int addW, size_t addC,
71	           const NVCVChannelManip manip, int width, int height)
72	          : m_dst {dst},
73	            m_addN{addN},
74	            m_addY{addH},
75	            m_addX{addW},
76	            m_wdth{width},
77	            m_hght{height} {_init(addC, remapC<N>(manip)); }
78	
79	    __device__ __forceinline__
80	    int width() const { return m_wdth; }
81	
82	    __device__ __forceinline__
83	    int height() const { return m_hght; }
84	
85	    __device__ __forceinline__
86	    DstT *ptr(const uint n, const int y, const int x) { return m_dst + n * m_addN + (y * m_addY + x * m_addX); }
87	
88	    template <typename SrcT, class = cuda::Require<cuda::HasTypeTraits<SrcT> > >
89	    __device__ __forceinline__
90	    void operator()(const uint n, const int y, const int x, const SrcT val)
91	    {
92	        static_assert(cuda::NumElements<SrcT> == N);
93	
94	        // Set destination pointer to correct pixel (batch, row, & column).
95	        DstT *dst = ptr(n, y, x);
96	
97	        // Shuffle pixel channels.
98	        if constexpr (cuda::NumComponents<SrcT> > 1) {
99	            dst[m_mapC[0]] = cuda::SaturateCast<DstT>(val.x);
100	            dst[m_mapC[1]] = cuda::SaturateCast<DstT>(val.y);
101	            if constexpr (N >= 3) dst[m_mapC[2]] = cuda::SaturateCast<DstT>(val.z);
102	            if constexpr (N == 4) dst[m_mapC[3]] = cuda::SaturateCast<DstT>(val.w);
103	        }
104	        else if constexpr (cuda::NumComponents<SrcT> == 1)
105	             *dst = cuda::SaturateCast<DstT>(val.x);
106	        else *dst = cuda::SaturateCast<DstT>(val);
107	    }
108	
109	private:
110	    void _init(size_t addC, uchar4 mapC)
111	    {
112	        m_mapC[0] = mapC.x * addC;
113	        if constexpr (N >= 2) m_mapC[1] = mapC.y * addC;
114	        if constexpr (N >= 3) m_mapC[2] = mapC.z * addC;
115	        if constexpr (N == 4) m_mapC[3] = mapC.w * addC;
116	    }
117	
118	    size_t m_mapC[N];
119	    size_t m_addN;
120	    int    m_addY, m_addX;
121	    int    m_wdth, m_hght;
122	    DstT  *m_dst;
123	};
124	
125	template<typename PixelT, typename BaseT>
126	__device__ __forceinline__ PixelT MakePlanarPixel(const BaseT *plane0, int64_t planeStride)
127	{
128	    static_assert(cuda::NumElements<PixelT> == 1 || cuda::NumElements<PixelT> == 3);
129	
130	    if constexpr (cuda::NumElements<PixelT> == 1)
131	    {
132	        return PixelT{plane0[0]};
133	    }
134	    else
135	    {
136	        return PixelT{plane0[0], plane0[planeStride], plane0[2 * planeStride]};
137	    }
138	}
139	
140	template<typename SrcT>
141	class TensorPlanarSrc
142	{
143	public:
144	    using ValueType = SrcT;
145	    using BaseT     = cuda::BaseType<SrcT>;
146	
147	    TensorPlanarSrc(const nvcv::TensorDataStridedCuda &srcData,
148	                    const nvcv::TensorDataAccessStridedImagePlanar &srcAccess)
149	        : m_src{reinterpret_cast<const BaseT *>(srcData.basePtr())}
150	        , m_sampleStride{srcAccess.sampleStride() / static_cast<int64_t>(sizeof(BaseT))}
151	        , m_planeStride{srcAccess.planeStride() / static_cast<int64_t>(sizeof(BaseT))}
152	        , m_rowStride{srcAccess.rowStride() / static_cast<int64_t>(sizeof(BaseT))}
153	        , m_colStride{srcAccess.colStride() / static_cast<int64_t>(sizeof(BaseT))}
154	    {
155	    }
156	
157	    __device__ __forceinline__ SrcT read(int n, int y, int x) const
158	    {
