231	__device__ __forceinline__ void WriteBilinearPixel(DstMap dst, const SrcWrapper &src, int n, int dstY, int dstX,
232	                                                   float fx, float fy, int srcW, int srcH, float scale, float offset,
233	                                                   bool srcCast)
234	{
235	    using SrcT = std::remove_cv_t<typename SrcWrapper::ValueType>;
236	
237	    int sx0 = __float2int_rd(fx);
238	    int sy0 = __float2int_rd(fy);
239	    int sx1 = cuda::min(sx0 + 1, srcW - 1);
240	    int sy1 = cuda::min(sy0 + 1, srcH - 1);
241	
242	    fx -= sx0;
243	    fy -= sy0;
244	    sx0 = cuda::max(0, sx0);
245	    sy0 = cuda::max(0, sy0);
246	    sx1 = sx1 > sx0 ? sx1 : sx0;
247	
248	    const SrcT src00 = ReadPixel(src, n, sy0, sx0);
249	    const SrcT src01 = ReadPixel(src, n, sy0, sx1);
250	    const SrcT src10 = ReadPixel(src, n, sy1, sx0);
251	    const SrcT src11 = ReadPixel(src, n, sy1, sx1);
252	
253	    if (srcCast)
254	    {
255	        dst(n, dstY, dstX, scale * cuda::SaturateCast<SrcT>((1-fy) * ((1-fx) * src00 + src01 * fx)
256	                                                            + fy  * ((1-fx) * src10 + src11 * fx)) + offset);
257	    }
258	    else
259	    {
260	        dst(n, dstY, dstX, scale * ((1-fy) * ((1-fx) * src00 + src01 * fx)
261	                                    + fy  * ((1-fx) * src10 + src11 * fx)) + offset);
262	    }
