296	
297	    if (dst_x < dst.width() && dst_y < dst.height())
298	    {
299	        // Use floating-point space for bi-linear interpolation computation.
300	        // Compute x and y coordinates, source data position, and weights.
301	        float fx = (dst_x + crop.x + 0.5f) * resize.x - 0.5f;
302	        float fy = (dst_y + crop.y + 0.5f) * resize.y - 0.5f;
