304	        // Bi-linear interpolation, rescale, channel manipulation, convert type, and reformat.
305	        WriteBilinearPixel(dst, src, (int)blockIdx.z, dst_y, dst_x, fx, fy, src_w, src_h, scale, offset, src_cast);
