template<typename SrcT, typename DstT>
void resizeCropConvertReformat(const nvcv::TensorDataStridedCuda &srcData, const nvcv::TensorDataStridedCuda &dstData,
                               const NVCVSize2D resizeDim, NVCVInterpolationType interp, const int2 cropPos,
                               const NVCVChannelManip manip, float scale, float offset, bool srcCast,
                               cudaStream_t stream)

{
    constexpr uint NumElems = cuda::NumElements<SrcT>;

    using SrcBaseT = cuda::BaseType<SrcT>;
    using DstBaseT = cuda::BaseType<DstT>;
    using DstMapT  = DstMap<DstBaseT, NumElems>;
    using StrideT  = int32_t;

content.content:
420	    using StrideT  = int32_t;
421	
422	    auto srcAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(srcData);
423	    NVCV_ASSERT(srcAccess);
424	
425	    auto dstAccess = nvcv::TensorDataAccessStridedImagePlanar::Create(dstData);
426	    NVCV_ASSERT(dstAccess);
427	
428	    const int samples  = srcAccess->numSamples();
429	    const int channels = srcAccess->numChannels();
430	    const int src_w    = srcAccess->numCols();
431	    const int src_h    = srcAccess->numRows();
432	    const int dst_w    = dstAccess->numCols();
433	    const int dst_h    = dstAccess->numRows();
434	
435	    NVCV_ASSERT(samples == dstAccess->numSamples());
436	    NVCV_ASSERT(channels == dstAccess->numChannels());
437	
438	    float2 resize{(float)src_w / resizeDim.w, (float)src_h / resizeDim.h};
439	
440	    const int planes = dstAccess->numPlanes();
441	
442	    const size_t addC = (planes > 1 ? dstAccess->planeStride() / sizeof(DstBaseT) : 1);
443	    const int    addW = channels / planes; // 1 if planar; channels if not.
444	    const int    addH = static_cast<int>(dstAccess->rowStride() / sizeof(DstBaseT));
445	    const size_t addN = dstAccess->rowStride() * dst_h * dstAccess->numPlanes() / sizeof(DstBaseT);
446	
447	    DstBaseT *dstPtr = reinterpret_cast<DstBaseT *>(dstData.basePtr());
448	
449	    DstMapT dst{dstPtr, addN, addH, addW, addC, manip, dst_w, dst_h};
450	
451	    const int THREADS_PER_BLOCK = 256; // 256?  64?
452	    const int BLOCK_WIDTH       = 16;  // as in 32x4 or 32x8.  16x8 and 16x16 are also viable
453	
454	    const dim3 blockSize(BLOCK_WIDTH, THREADS_PER_BLOCK / BLOCK_WIDTH, 1);
455	    const dim3 gridSize(util::DivUp(dst_w, blockSize.x), util::DivUp(dst_h, blockSize.y), samples);
456	
457	    // Note: resize is fundamentally a gather memory operation, with a little bit of compute
458	    //       our goals are to (a) maximize throughput, and (b) minimize occupancy for the same performance
459	    // The channel dispatcher uses scalar SrcT only for a single-channel input, which has one plane.
460	    if constexpr (NumElems > 1)
461	    {
462	        if (srcAccess->numPlanes() > 1)
463	        {
464	            TensorPlanarSrc<SrcT> src{srcData, *srcAccess};
465	            LaunchTensorResizeCrop(dst, src, gridSize, blockSize, stream, interp, src_w, src_h, resize, cropPos, scale,
466	                                   offset, srcCast);
467	            return;
468	        }
469	    }
470	
471	    auto src = cuda::CreateTensorWrapNHW<const SrcT, StrideT>(srcData);
472	    LaunchTensorResizeCrop(dst, src, gridSize, blockSize, stream, interp, src_w, src_h, resize, cropPos, scale, offset,
473	                           srcCast);
474	} //resize
